// Append renders the SVG presentation while reusing buffers retained by w.
func (w *ArasySplashStackedWorkspace) Append(timeline anim.Timeline, viewport math2d.Rect, resources ArasySplashStackedResources) []render.Command {
	if w == nil {
		return AppendArasySplashStacked(nil, timeline, viewport, resources)
	}
	if cap(w.commands) < ArasySplashStackedAssetMetrics.CommandCapacity {
		w.commands = make([]render.Command, 0, ArasySplashStackedAssetMetrics.CommandCapacity)
	}
	scale := arasySplashStackedScale(viewport)
	w.lod = svgLODWithHysteresis(w.lod, w.lodReady, scale)
	w.lodReady = true
	w.frameMetrics = ArasySplashStackedFrameMetrics{LOD: w.lod, Tolerance: svgLODTolerance(w.lod)}
	w.commands = appendArasySplashStacked(
		w.commands[:0], timeline, viewport, resources, &w.builder,
		w.fills[:], w.strokes[:], w.frameMetrics.Tolerance, &w.frameMetrics,
	)
	return w.commands
}

// FrameMetrics returns traversal and LOD data from the latest Append call.
func (w *ArasySplashStackedWorkspace) FrameMetrics() ArasySplashStackedFrameMetrics {
	if w == nil {
		return ArasySplashStackedFrameMetrics{}
	}
	return w.frameMetrics
}

// AppendArasySplashStacked appends the SVG presentation at timeline time into dst.
func AppendArasySplashStacked(dst []render.Command, timeline anim.Timeline, viewport math2d.Rect, resources ArasySplashStackedResources) []render.Command {
	scale := arasySplashStackedScale(viewport)
	return appendArasySplashStacked(
		dst, timeline, viewport, resources, nil, nil, nil,
		svgLODTolerance(svgLOD(scale)), nil,
	)
}

func arasySplashStackedScale(viewport math2d.Rect) float64 {
	return math.Min(viewport.Width()/840, viewport.Height()/750)
}

func appendArasySplashStacked(
	dst []render.Command,
	timeline anim.Timeline,
	viewport math2d.Rect,
	resources ArasySplashStackedResources,
	builder *render.Builder,
	fillWorkspaces []vector.FillWorkspace,
	strokeWorkspaces []vector.StrokeWorkspace,
	tolerance float64,
	frameMetrics *ArasySplashStackedFrameMetrics,
) []render.Command {
	if builder == nil {
		builder = &render.Builder{}
	}
	builder.Reset(dst)
	scale := arasySplashStackedScale(viewport)
	offset := math2d.Vec2{
		X: viewport.Min.X + (viewport.Width()-840*scale)*0.5 - 0*scale,
		Y: viewport.Min.Y + (viewport.Height()-750*scale)*0.5 - 0*scale,
	}
	builder.Push(render.Group{Transform: math2d.Translate(offset).Mul(math2d.Scale(math2d.Vec2{X: scale, Y: scale})), Opacity: 1})
	// Bounds checks pay for themselves on larger node sets. Small assets skip
	// the per-node matrix/bounds work and retain the straight traversal.
	appendSVGNode(
		builder, arasySplashStackedNodes, 0, timeline, resources.font,
		fillWorkspaces, strokeWorkspaces, tolerance,
		math2d.Rect{Min: math2d.Vec2{X: 0, Y: 0}, Max: math2d.Vec2{X: 840, Y: 750}}, ArasySplashStackedAssetMetrics.Nodes >= 32, math2d.Identity(), frameMetrics,
	)
	builder.Pop()
	return builder.Commands()
}

func (r ArasySplashStackedResources) font(field uint16) render.FontID {
	switch field {
	default:
		return 0
	}
}
